bson/iterator.go (reference skeleton)
```python
package bson

type ArrayIterator struct {
	arr     *Array
	index   int
	current int
}

func (it *ArrayIterator) Next() bool {
	if it.arr == nil || it.index >= len(it.arr.values) {
		return false
	}
	it.current = it.arr.values[it.index]
	it.index++
	return true
}

func (it *ArrayIterator) Value() int {
	return it.current
}

func (it *ArrayIterator) Err() error {
	return nil
}
```

