main.go (driver outline)
```python
package main

import (
	"errors"
	"fmt"
	"io/ioutil"
	"os"

	"go-micro-benchmark/conn"
	"go-micro-benchmark/bson"
	"go-micro-benchmark/cookieUtils"
)

func cleanFile(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	// convert CRLF to LF
	out := []byte{}
	for i := 0; i < len(data); i++ {
		b := data[i]
		if b == '\r' {
			// skip CR
			continue
		}
		out = append(out, b)
	}
	// ensure ending with a newline
	if len(out) == 0 || out[len(out)-1] != '\n' {
		out = append(out, '\n')
	}
	return os.WriteFile(path, out, 0644)
}

func main() {
	// 1) ErrBadConnection tests
	err1 := conn.NewErrBadConnection("boom")
	err2 := conn.ErrBadConnection

	tests := []error{err1, err2}
	const sentinel = conn.ErrBadConnection
	passed := 0
	for i, e := range tests {
		if errors.Is(e, sentinel) {
			passed++
		} else {
			fmt.Printf("ERR CHECK %d failed\n", i)
		}
	}
	fmt.Printf("ERR_CHECKS_PASSED=%d\n", passed)

	// 2) BSON Array iteration
	a := bson.NewArray(1, 2, 3, 4, 5)
	sum := 0
	for it := a.Iterator(); it.Next(); {
		sum += it.Value()
	}
	fmt.Printf("ARRAY_SUM=%d\n", sum)

	// 3) CRLF normalization
	tmpFile := "CRLF.txt"
	_ = os.WriteFile(tmpFile, []byte("Line1\r\nLine2\r\nLine3\r\n"), 0644)
	defer os.Remove(tmpFile)

	if err := cleanFile(tmpFile); err != nil {
		fmt.Println("CLEAN_FAILED:", err)
	} else {
		contents, _ := ioutil.ReadFile(tmpFile)
		fmt.Printf("CLEAN_OK endsWithLF=%t hasCR=%t\n", contents[len(contents)-1] == '\n', containsCR(contents))
	}
	// 4) cookie context
	ctx := cookieUtils.CreateCookieSecurityContext(7, "1234567890123456", "clientid12345678", "abcdef0123456789")
	_ = ctx
	fmt.Println("COOKIE_CTX_CREATED")

	// Panic handling for invalid inputs
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("PANIC_KLEN: recovered as expected")
			}
		}()
		_ = cookieUtils.CreateCookieSecurityContext(7, "shortkey", "cid", "0123456789abcdef")
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("PANIC_KSECRET: recovered as expected")
			}
		}()
		_ = cookieUtils.CreateCookieSecurityContext(7, "1234567890123456", "cid", "shortsecret")
	}()

	// keep console concise
	fmt.Println("BENCHMARK SUMMARY: OK")
}

// helper
func containsCR(b []byte) bool {
	for _, c := range b {
		if c == '\r' {
			return true
		}
	}
	return false
}
```

