// BEFORE: minimal implementations with a deliberate rotate bug
#include <cmath>
#include "Matrix3.h"

template <typename T>
Matrix3<T> Matrix3<T>::identity() {
    return Matrix3<T>(); // identity by default
}

template <typename T>
Matrix3<T> Matrix3<T>::translate(T x, T y) {
    Matrix3<T> M;
    M.m[0][2] = x;
    M.m[1][2] = y;
    return M;
}

template <typename T>
Matrix3<T> Matrix3<T>::rotate(T /*degrees*/) {
    // DELIBERATE BUG: incorrect rotation matrix (signs swapped)
    Matrix3<T> M;
    M.m[0][0] = T(0); M.m[0][1] = T(1); M.m[0][2] = T(0);
    M.m[1][0] = T(-1); M.m[1][1] = T(0); M.m[1][2] = T(0);
    M.m[2][0] = T(0); M.m[2][1] = T(0); M.m[2][2] = T(1);
    return M;
}

template <typename T>
Matrix3<T> Matrix3<T>::scale(T sx, T sy) {
    Matrix3<T> M;
    M.m[0][0] = sx; M.m[0][1] = T(0); M.m[0][2] = T(0);
    M.m[1][0] = T(0); M.m[1][1] = sy; M.m[1][2] = T(0);
    M.m[2][0] = T(0); M.m[2][1] = T(0); M.m[2][2] = T(1);
    return M;
}

// Explicit template instantiations may be needed by build system
template struct Matrix3<float>;
template struct Matrix3<double>;

template <typename T>
Vector3<T> Matrix3<T>::operator*(const Vector3<T>& v) const {
    return Vector3<T>(
        m[0][0] * v.x + m[0][1] * v.y + m[0][2] * v.z,
        m[1][0] * v.x + m[1][1] * v.y + m[1][2] * v.z,
        m[2][0] * v.x + m[2][1] * v.y + m[2][2] * v.z
    );
}

template <typename T>
Matrix3<T> Matrix3<T>::operator*(const Matrix3<T>& O) const {
    Matrix3<T> R;
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j) {
            R.m[i][j] = T(0);
            for (int k = 0; k < 3; ++k)
                R.m[i][j] += m[i][k] * O.m[k][j];
        }
    return R;
}
```

