            fprintf(stderr, "missing text for encode\n");
            return 1;
        }
        const char *text = argv[2];
        unsigned char out[256];
        int written = b64_encode(text, strlen(text), out, sizeof(out));
        if (written < 0) {
            fprintf(stderr, "encode error\n");
            return 1;
        }
        printf("%s\n", (char*)out);
        return 0;
    } else if (strcmp(argv[1], "size") == 0) {
        if (argc < 3) {
            fprintf(stderr, "missing size\n");
            return 1;
        }
        size_t n = (size_t)strtoull(argv[2], NULL, 10);
        const char *fmt = format_size(n);
        printf("%s\n", fmt);
        return 0;
    } else if (strcmp(argv[1], "uid") == 0) {
        if (argc < 3) {
            fprintf(stderr, "missing pid\n");
            return 1;
        }
        pid_t pid = (pid_t)atoi(argv[2]);
        uid_t uid;
        if (getuid_by_pid(pid, &uid)) {
            printf("%u\n", (unsigned)uid);
            return 0;
        } else {
            fprintf(stderr, "uid lookup failed\n");
            return 1;
        }
    } else if (strcmp(argv[1], "gid") == 0) {
        if (argc < 3) {
            fprintf(stderr, "missing pid\n");
            return 1;
        }
        pid_t pid = (pid_t)atoi(argv[2]);
        gid_t gid;
        if (getgid_by_pid(pid, &gid)) {
            printf("%u\n", (unsigned)gid);
            return 0;
        } else {
            fprintf(stderr, "gid lookup failed\n");
            return 1;
        }
    } else if (strcmp(argv[1], "mount") == 0) {
        if (argc < 3) {
            fprintf(stderr, "missing path\n");
            return 1;
        }
        struct mntent *mnt = find_mount_point(argv[2]);
        if (mnt) {
            printf("MNT=%s, DEV=%s\n", mnt->mnt_type, mnt->mnt_fsname);
            return 0;
        } else {
            printf("MNT=unknown, DEV=unknown\n");
            return 0;
        }
    }

    fprintf(stderr, "unknown command\n");
    print_help();
    return 1;
