```python
# app/scripts/verify-platforms.js (final)
'use strict';
const fs = require('fs');
const path = require('path');

(function main() {
  const tsPath = path.join(__dirname, '../src/instance-platforms.ts');
  const tsContent = fs.readFileSync(tsPath, 'utf8');

  // Extract exported constants: name = value;
  const exportRegex = /export\s+const\s+(\w+)\s*=\s*([^;]+);/g;
  const newConsts = {};
  const deprecatedConsts = {};

  let m;
  while ((m = exportRegex.exec(tsContent)) !== null) {
    const name = m[1];
    const valueExpr = m[2].trim();
    let value;
    if ((valueExpr.startsWith("'") && valueExpr.endsWith("'")) || (valueExpr.startsWith('"') && valueExpr.endsWith('"'))) {
      value = valueExpr.slice(1, -1);
    } else {
      value = valueExpr;
    }

    if (name.endsWith('PlatformDeprecated')) {
      deprecatedConsts[name] = value;
    } else {
      newConsts[name] = value;
    }
  }

  // Canonical labels mapping for new constants
  const canonicalMap = {
    LinuxUnixPlatform: 'Linux/UNIX',
    RedHatEnterpriseLinuxPlatform: 'Red Hat Enterprise Linux',
    SuseLinuxPlatform: 'SUSE Linux',
    WindowsPlatform: 'Windows',
    WindowsWithSqlServerPlatform: 'Windows with SQL Server',
    WindowsWithSqlServerEnterprisePlatform: 'Windows with SQL Server Enterprise',
    WindowsWithSqlServerStandardPlatform: 'Windows with SQL Server Standard',
    WindowsWithSqlServerWebPlatform: 'Windows with SQL Server Web'
  };

  let ok = true;
  const logs = [];

  // Verify new constants match canonical labels
  for (const name of Object.keys(newConsts)) {
    const expected = canonicalMap[name];
    const value = newConsts[name];
    if (expected === undefined) {
      logs.push(`UNKNOWN_NEW_CONST ${name}=${value}`);
      continue;
    }
    if (value !== expected) {
      ok = false;
      logs.push(`MISMATCH ${name}: value=${value} expected=${expected}`);
    } else {
      logs.push(`OK ${name}: ${value}`);
    }
  }

  // Verify deprecated constants mirror the new ones
  for (const depName of Object.keys(deprecatedConsts)) {
    const baseName = depName.replace('Deprecated', '');
    const baseValue = newConsts[baseName];
    const depValue = deprecatedConsts[depName];
    if (baseValue === undefined) {
      logs.push(`DEPRECATED_UNKNOWN_BASE ${depName}`);
      ok = false;
      continue;
    }
    if (depValue !== baseValue) {
      ok = false;
      logs.push(`DEPRECATED_MISMATCH ${depName}: value=${depValue} vs base=${baseValue}`);
    } else {
      logs.push(`DEPRECATED_OK ${depName}: ${depValue}`);
    }
  }

  // Write log
  logs.unshift(`Platform verification report: ${new Date().toISOString()}`);
  const finalLine = ok ? 'OK: All platform constants verified' : 'ERROR: Platform verification failed';
  logs.push(finalLine);

  const logDir = path.join(__dirname, '../logs');
  fs.mkdirSync(logDir, { recursive: true });
  const logPath = path.join(logDir, 'verify.log');
  fs.writeFileSync(logPath, logs.join('\n'), 'utf8');

  if (!ok) {
    process.exit(1);
  } else {
    console.log('All platform constants verified');
    process.exit(0);
  }
})();
```

