    // Tiny, deterministic synthetic workload
    volatile int acc = 0;
    int limit = mParams.B * mParams.G * mParams.Cpg * mParams.Fpg;
    int mod = mParams.KH + mParams.KW + mParams.StrideH + mParams.StrideW;
    for (int i = 0; i < limit; ++i) {
      acc += (i % (mod == 0 ? 1 : mod));
    }
    (void)acc; // quiet unused in release
  }

private:
  Params mParams;
};

// Simple test entry
struct TestEntry {
  std::string name;
  std::function<void()> runner;
};

// Registry for tests
class TestRegistry {
public:
  static void Register(const std::string& name, std::function<void()> runner) {
    getRegistry().push_back({name, runner});
  }
  static const std::vector<TestEntry>& Tests() {
    return getRegistry();
  }
private:
  static std::vector<TestEntry>& getRegistry() {
    static std::vector<TestEntry> s;
    return s;
  }
};

// Helper to register a single test with captured Params
template <typename Params>
void RegisterSingleTest(const std::string& name, const Params& p) {
  TestRegistry::Register(name, [p]() {
    Conv2dShortExecuteTest<Params> t(p);
    t.Run();
  });
}
