#include "conv2d_harness.h"
#include <iostream>
#include <fstream>
#include <string>

// Define a simple Params struct matching the specification
struct Params {
  int B;
  int G;
  int Cpg;
  int Fpg;
  int KH;
  int KW;
  int StrideH;
  int StrideW;
};

// Forward declaration
void RegisterShortExecuteTests();

static void ensureLogsDir() {
  // Best-effort creation; ignore failure if it already exists
  mkdir("logs", 0777);
}

// Register a handful of parameterized tests
void RegisterShortExecuteTests() {
  Params p1{1, 1, 16, 32, 3, 3, 1, 1};
  RegisterSingleTest<Params>("B1/G1/Cpg16/Fpg32/KH3/KW3_Stride1_1", p1);

  Params p2{2, 2, 8, 64, 5, 5, 2, 2};
  RegisterSingleTest<Params>("B2/G2/Cpg8/Fpg64/KH5/KW5_Stride2_2", p2);

  Params p3{4, 1, 32, 16, 3, 5, 1, 2};
  RegisterSingleTest<Params>("B4/G1/Cpg32/Fpg16/KH3/KW5_Stride1_2", p3);

  Params p4{1, 2, 8, 32, 3, 3, 2, 1};
  RegisterSingleTest<Params>("B1/G2/Cpg8/Fpg32/KH3/KW3_Stride2_1", p4);
}

int main() {
  ensureLogsDir();

  std::ofstream log("logs/run.log", std::ios::app);
  if (!log) {
    // If log can't be opened, still proceed and write to stdout
  }

  // Register tests
  RegisterShortExecuteTests();

  auto& tests = TestRegistry::Tests();
  log << "Registered " << tests.size() << " tests\n";
  std::cout << "Registered " << tests.size() << " tests" << std::endl;

  for (const auto& t : tests) {
    std::cout << "Running test: " << t.name << std::endl;
